/**
 * Shopify headless configuration for Magic Meals.
 *
 * Only PUBLIC values belong here (the Storefront token is public by design). Never paste an Admin API key.
 * Product ids are NOT listed here any more: shopify-catalog.js (generated by `python tools/shopify-sync.py`) holds the
 * website-product -> Shopify-variant mapping, and shopify-connector.js checks it against the live store at checkout.
 */
window.SHOPIFY_CONFIG = {
  // Store (the "My Store 2" store; NOT the uvankids.com store)
  shopDomain: '1z10zd-y0.myshopify.com',

  // PUBLIC Storefront API access token
  storefrontAccessToken: 'c490756ca639d9a1a1ea506ff0631bc0',

  // Pinned on purpose: an unpinned or retired version is silently served as a different one.
  apiVersion: '2026-07',

  // Pack sizes on the site (1 / 3 / 6) are sold as Shopify VARIANTS of the same product, with the site's own price:
  // single pouch = "Default Title" (or "Single"), "Pack of 3", "Pack of 6". A pack with no variant is blocked at checkout
  // instead of being sent as the wrong thing. Titles are matched exactly (case-insensitive) by tools/shopify-sync.py.

  // Build Your Own Box: the box discount (2 meals 5%, 4 meals 10%, 6 meals 15%) is a Shopify discount code. Create three
  // percentage discount codes in Shopify admin and put them here. While a size is empty, that box is blocked at checkout.
  // Setup steps: shopify-box-discounts.md. Until the codes exist in Shopify, box checkout stops with a clear message.
  byobDiscountCodes: {
    2: 'BYOB2',
    4: 'BYOB4',
    6: 'BYOB6'
  }
};
